PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE news (
  id text primary key,
  title_en text not null default '',
  title_my text not null default '',
  body_en text not null default '',
  body_my text not null default '',
  image_url text,
  published_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
INSERT INTO "news" ("id","title_en","title_my","body_en","body_my","image_url","published_at","created_at") VALUES('3913b2ff-7273-45b5-bdf6-e5433fb0e779','Football Tournament','ဘောလုံးပြိုင်ပွဲ','Total Team - 8','စုစုပေါင်း အသင်း - ၈ သင်း','/api/img/news/1788941989526-x4gqsy28.jpg','2026-09-13T00:00:00+00:00','2026-09-09T08:03:26.039246+00:00');
CREATE TABLE events (
  id text primary key,
  title_en text not null default '',
  title_my text not null default '',
  date text not null,
  time text,
  location_en text,
  location_my text,
  description_en text,
  description_my text,
  image_url text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
