INSERT INTO "events" ("id","title_en","title_my","date","time","location_en","location_my","description_en","description_my","image_url","created_at") VALUES('b7bc508a-d5c2-4530-9c89-fa8f19440148','BasketBall Tournament','BasketBall ပြိုင်ပွဲ','2026-09-13','8:00Am','School''s Big Gym','School''s Big Gym',replace('Requirement \nBasketball team uniform','\n',char(10)),replace('လိုအပ်ချက်များ\nBasketball အသင်းတူညီဝတ်စုံ','\n',char(10)),NULL,'2026-09-09T08:12:18.745878+00:00');
INSERT INTO "events" ("id","title_en","title_my","date","time","location_en","location_my","description_en","description_my","image_url","created_at") VALUES('b37bf068-aba9-450f-aeb7-e5c00e8e8a52','သင်ကြားရေးလမ်းညွှန်','သင်ကြားရေးလမ်းညွှန်','2026-09-10','9:00 AM - 13:00 PM','HOPE International School',NULL,replace('3နှစ်မှ 6နှစ်အရွယ်ကလေးများနှင့် မိဘများအတွက် လက်မလွှတ်သင့်သောအထူးအခွင့်အရေး✨\n\nကလေးကို ချော့ရမလား ဆူရမလား?\nကစားခိုင်းရမလား စာလုပ်ခိုင်းရမလား?\nအလိုလိုက်ပေးရမလား စည်းကမ်းကြီးရမလား?\n\nဇဝေဇဝါ ဖြစ်နေကြသော မိဘများ အတွက် ကိုရီးယားနိုင်ငံမှ ရောက်ရှိလာသော 𝐇𝐎𝐏𝐄 𝐈𝐧𝐭𝐞𝐫𝐧𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐒𝐜𝐡𝐨𝐨𝐥 ၏ ဆရာမ တစ်ဦးဖြစ်သော Mind Professor Dr. Gu Gyeong Hwa မှ အထူး Special Lecture ပို့ချပေးသွားမည် ဖြစ်ပါသည်။\n\nအခုပဲအမြန်ဆုံးစာရင်းပေးသွင်းလို့ရပါပြီ📣','\n',char(10)),replace('3နှစ်မှ 6နှစ်အရွယ်ကလေးများနှင့် မိဘများအတွက် လက်မလွှတ်သင့်သောအထူးအခွင့်အရေး✨\n\nကလေးကို ချော့ရမလား ဆူရမလား?\nကစားခိုင်းရမလား စာလုပ်ခိုင်းရမလား?\nအလိုလိုက်ပေးရမလား စည်းကမ်းကြီးရမလား?\n\nဇဝေဇဝါ ဖြစ်နေကြသော မိဘများ အတွက် ကိုရီးယားနိုင်ငံမှ ရောက်ရှိလာသော 𝐇𝐎𝐏𝐄 𝐈𝐧𝐭𝐞𝐫𝐧𝐚𝐭𝐢𝐨𝐧𝐚𝐥 𝐒𝐜𝐡𝐨𝐨𝐥 ၏ ဆရာမ တစ်ဦးဖြစ်သော Mind Professor Dr. Gu Gyeong Hwa မှ အထူး Special Lecture ပို့ချပေးသွားမည် ဖြစ်ပါသည်။\n\nအခုပဲအမြန်ဆုံးစာရင်းပေးသွင်းလို့ရပါပြီ📣','\n',char(10)),'/api/img/events/1788969591347-o52xq4dd.jpg','2026-09-09T15:59:52.457123+00:00');
CREATE TABLE site_content (
  key text primary key,
  value_en text not null default '',
  value_my text not null default '',
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('academics_intro','Our curriculum blends international teaching standards with the best of Myanmar culture. Students learn to think deeply, ask questions and apply their knowledge to real life.','ကျွန်ုပ်တို့၏ သင်ရိုးညွှန်းတမ်းသည် နိုင်ငံတကာ သင်ကြားရေး စံနှုန်းများနှင့် မြန်မာ့ယဉ်ကျေးမှု၏ အကောင်းဆုံးအရာများကို ပေါင်းစပ်ထားသည်။ ကျောင်းသားများသည် နက်နက်ရှိုင်းရှိုင်း တွေးခေါ်တတ်ရန်၊ မေးခွန်းထုတ်တတ်ရန်နှင့် မိမိတို့၏ အသိပညာကို လက်တွေ့ဘဝတွင် အသုံးချတတ်ရန် သင်ယူကြသည်။','2026-09-11T15:13:42.677Z');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('about_facts','{"title_en":"Our School at a Glance","title_my":"ကျောင်း၏ တစ်ချက်ကြည့်မြင်ကွင်း","facts":[{"number_en":"500+","number_my":"၅၀၀+","label_en":"Students","label_my":"ကျောင်းသား ကျောင်းသူများ"},{"number_en":"40+","number_my":"၄၀+","label_en":"Qualified Teachers","label_my":"အရည်အချင်းပြည့်မီ ဆရာ ဆရာမများ"},{"number_en":"12","number_my":"၁၂","label_en":"Years of Excellence","label_my":"နှစ်ပေါင်း အတွေ့အကြုံ"},{"number_en":"1:15","number_my":"၁:၁၅","label_en":"Teacher–Student Ratio","label_my":"ဆရာ–ကျောင်းသား အချိုး"}]}','{"title_en":"Our School at a Glance","title_my":"ကျောင်း၏ တစ်ချက်ကြည့်မြင်ကွင်း","facts":[{"number_en":"500+","number_my":"၅၀၀+","label_en":"Students","label_my":"ကျောင်းသား ကျောင်းသူများ"},{"number_en":"40+","number_my":"၄၀+","label_en":"Qualified Teachers","label_my":"အရည်အချင်းပြည့်မီ ဆရာ ဆရာမများ"},{"number_en":"12","number_my":"၁၂","label_en":"Years of Excellence","label_my":"နှစ်ပေါင်း အတွေ့အကြုံ"},{"number_en":"1:15","number_my":"၁:၁၅","label_en":"Teacher–Student Ratio","label_my":"ဆရာ–ကျောင်းသား အချိုး"}]}','2026-09-09T10:41:59.735878+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('about_intro','Hope International School is a vibrant learning community in Myanmar where international standards meet local values.','Hope အပြည်ပြည်ဆိုင်ရာကျောင်းသည် နိုင်ငံတကာ စံနှုန်းများနှင့် ဒေသဆိုင်ရာ တန်ဖိုးများ ပေါင်းစပ်ထားသော မြန်မာနိုင်ငံရှိ တက်ကြွသော သင်ယူမှု အသိုင်းအဝိုင်းတစ်ခုဖြစ်သည်။','2026-09-09T04:34:22.682142+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('about_mission_vision','{"mission_title_en":"Our Mission","mission_title_my":"ရည်ရွယ်ချက်","mission_text_en":"To nurture confident, compassionate and curious learners who think critically, communicate clearly and contribute positively to their community and the wider world.","mission_text_my":"ဝေဖန်ပိုင်းခြား တွေးခေါ်နိုင်သော၊ ရှင်းလင်းစွာ ပြောဆိုဆက်သွယ်နိုင်သော၊ မိမိပတ်ဝန်းကျင်နှင့် ကမ္ဘာ့အသိုင်းအဝိုင်းအတွက် အကျိုးပြုနိုင်သော ယုံကြည်မှုရှိသည့် ကြင်နာတတ်ပြီး စူးစမ်းလိုစိတ်ရှိသော သင်ယူသူများကို ပြုစုပျိုးထောင်ရန်။","vision_title_en":"Our Vision","vision_title_my":"မျှော်မှန်းချက်","vision_text_en":"To be the leading international school in Myanmar — a place where every student is known, valued and inspired to reach their full potential.","vision_text_my":"မြန်မာနိုင်ငံ၏ ဦးဆောင်သော နိုင်ငံတကာကျောင်း ဖြစ်လာရန် — ကျောင်းသားတိုင်းကို သိရှိနားလည်ကာ တန်ဖိုးထားပြီး မိမိ၏ အလားအလာ အပြည့်အဝ ရောက်ရှိရန် စေ့ဆော်ပေးသော နေရာ။","extra_cards":[]}','{"mission_title_en":"Our Mission","mission_title_my":"ရည်ရွယ်ချက်","mission_text_en":"To nurture confident, compassionate and curious learners who think critically, communicate clearly and contribute positively to their community and the wider world.","mission_text_my":"ဝေဖန်ပိုင်းခြား တွေးခေါ်နိုင်သော၊ ရှင်းလင်းစွာ ပြောဆိုဆက်သွယ်နိုင်သော၊ မိမိပတ်ဝန်းကျင်နှင့် ကမ္ဘာ့အသိုင်းအဝိုင်းအတွက် အကျိုးပြုနိုင်သော ယုံကြည်မှုရှိသည့် ကြင်နာတတ်ပြီး စူးစမ်းလိုစိတ်ရှိသော သင်ယူသူများကို ပြုစုပျိုးထောင်ရန်။","vision_title_en":"Our Vision","vision_title_my":"မျှော်မှန်းချက်","vision_text_en":"To be the leading international school in Myanmar — a place where every student is known, valued and inspired to reach their full potential.","vision_text_my":"မြန်မာနိုင်ငံ၏ ဦးဆောင်သော နိုင်ငံတကာကျောင်း ဖြစ်လာရန် — ကျောင်းသားတိုင်းကို သိရှိနားလည်ကာ တန်ဖိုးထားပြီး မိမိ၏ အလားအလာ အပြည့်အဝ ရောက်ရှိရန် စေ့ဆော်ပေးသော နေရာ။","extra_cards":[]}','2026-09-09T10:41:59.524932+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('about_sections','[{"eyebrow_en":"","eyebrow_my":"","title_en":"","title_my":"","cards":[]}]','[{"eyebrow_en":"","eyebrow_my":"","title_en":"","title_my":"","cards":[]}]','2026-09-09T10:41:59.824229+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('about_values','{"title_en":"Our Core Values","title_my":"အခြေခံတန်ဖိုးများ","values":[{"title_en":"Respect","title_my":"လေးစားမှု","desc_en":"We honour every person, culture and idea, and treat others with kindness and fairness.","desc_my":"လူတိုင်း၊ ယဉ်ကျေးမှုတိုင်းနှင့် အယူအဆတိုင်းကို လေးစားပြီး ကြင်နာမှုနှင့် တရားမျှတမှုဖြင့် ဆက်ဆံပါသည်။"},{"title_en":"Integrity","title_my":"ရိုးသားမှု","desc_en":"We act honestly and take responsibility for our words and actions.","desc_my":"ရိုးသားစွာ ပြုမူပြီး မိမိ၏ စကားနှင့် အပြုအမူများအတွက် တာဝန်ယူပါသည်။"},{"title_en":"Excellence","title_my":"ထူးချွန်မှု","desc_en":"We set high standards, work hard and always try to improve.","desc_my":"မြင့်မားသော စံနှုန်းများ သတ်မှတ်ကာ ကြိုးစားပြီး အမြဲတမ်း တိုးတက်အောင် ကြိုးပမ်းပါသည်။"},{"title_en":"Community","title_my":"အသိုင်းအဝိုင်း","desc_en":"We care for one another and work together — students, families and staff.","desc_my":"ကျောင်းသား၊ မိသားစုနှင့် ဝန်ထမ်းများ — အချင်းချင်း ဂရုစိုက်ပြီး အတူတကွ လုပ်ဆောင်ပါသည်။"}]}','{"title_en":"Our Core Values","title_my":"အခြေခံတန်ဖိုးများ","values":[{"title_en":"Respect","title_my":"လေးစားမှု","desc_en":"We honour every person, culture and idea, and treat others with kindness and fairness.","desc_my":"လူတိုင်း၊ ယဉ်ကျေးမှုတိုင်းနှင့် အယူအဆတိုင်းကို လေးစားပြီး ကြင်နာမှုနှင့် တရားမျှတမှုဖြင့် ဆက်ဆံပါသည်။"},{"title_en":"Integrity","title_my":"ရိုးသားမှု","desc_en":"We act honestly and take responsibility for our words and actions.","desc_my":"ရိုးသားစွာ ပြုမူပြီး မိမိ၏ စကားနှင့် အပြုအမူများအတွက် တာဝန်ယူပါသည်။"},{"title_en":"Excellence","title_my":"ထူးချွန်မှု","desc_en":"We set high standards, work hard and always try to improve.","desc_my":"မြင့်မားသော စံနှုန်းများ သတ်မှတ်ကာ ကြိုးစားပြီး အမြဲတမ်း တိုးတက်အောင် ကြိုးပမ်းပါသည်။"},{"title_en":"Community","title_my":"အသိုင်းအဝိုင်း","desc_en":"We care for one another and work together — students, families and staff.","desc_my":"ကျောင်းသား၊ မိသားစုနှင့် ဝန်ထမ်းများ — အချင်းချင်း ဂရုစိုက်ပြီး အတူတကွ လုပ်ဆောင်ပါသည်။"}]}','2026-09-09T10:41:59.635966+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('about_why_choose','{"title_en":"Why Choose Hope?","title_my":"Hope ကို ဘာကြောင့် ရွေးချယ်သင့်သလဲ။","items":[{"icon":"🏫","title_en":"International Standards","title_my":"နိုင်ငံတကာ စံနှုန်းများ","text_en":"A balanced international curriculum from Early Years to Grade 12 — taught in English with Myanmar language and culture at its heart, opening doors to universities worldwide.","text_my":"နို့ဆိုင်းမှ ဂရိတ် ၁၂ အထိ မျှတသော နိုင်ငံတကာ သင်ရိုးညွှန်းတမ်း — အင်္ဂလိပ်ဘာသာဖြင့် သင်ကြားပြီး မြန်မာဘာသာနှင့် ယဉ်ကျေးမှုကို အခြေခံထားကာ ကမ္ဘာ့တက္ကသိုလ်များဆီ လမ်းဖွင့်ပေးပါသည်။"},{"icon":"👩‍🏫","title_en":"Experienced Teachers","title_my":"အတွေ့အကြုံရှိ ဆရာ ဆရာမများ","text_en":"40+ qualified teachers and a 1:15 teacher–student ratio mean small classes, individual attention and role models who care about every child.","text_my":"အရည်အချင်းပြည့်မီ ဆရာ ဆရာမ ၄၀ ကျော်နှင့် ဆရာ–ကျောင်းသား ၁:၁၅ အချိုးကြောင့် အတန်းငယ်များ၊ တစ်ယောက်ချင်း ဂရုစိုက်မှုနှင့် ကလေးတိုင်းကို ချစ်မြတ်နိုးသော ဆရာကောင်းများ ရရှိပါသည်။"},{"icon":"🧠","title_en":"Mind Education","title_my":"စိတ်ပညာရေး","text_en":"Mind education lectures by visiting experts — like Professor Dr. Gu Gyeong Hwa from Korea — and character education woven into daily learning build confidence, empathy and healthy attitudes.","text_my":"ကိုရီးယားနိုင်ငံမှ ဒေါက်တာ Gu Gyeong Hwa ကဲ့သို့ ကျွမ်းကျင်သူများ၏ စိတ်ပညာရေး ဟောပြောချက်များနှင့် နေ့စဉ်သင်ကြားမှုထဲတွင် ထည့်သွင်းထားသော စရိုက်ပညာတို့က ယုံကြည်မှု၊ သနားကြင်နာမှုနှင့် ကျန်းမာသော စိတ်သဘောထားများ ဖြစ်စေပါသည်။"},{"icon":"⚽","title_en":"Extra-Curricular Activities","title_my":"ပြင်ပလှုပ်ရှားမှုများ","text_en":"Football, basketball, swimming, robotics, music and traditional Myanmar arts — a wide range of activities helps every student discover their strengths beyond the classroom.","text_my":"ဘောလုံး၊ ဘတ်စကက်ဘော၊ ရေကူး၊ စက်ရုပ်၊ တေးဂီတနှင့် မြန်မာရိုးရာအနုပညာ — ပြင်ပလှုပ်ရှားမှုများစွာက ကျောင်းသားတိုင်း၏ စွမ်းရည်ထူးချွန်မှုကို စာသင်ခန်းပြင်ပတွင် ရှာဖွေတွေ့ရှိစေပါသည်။"},{"icon":"🛡️","title_en":"Facilities, Safety & Location","title_my":"အဆောက်အအုံ၊ လုံခြုံရေးနှင့် တည်နေရာ","text_en":"Modern facilities, a caring culture of safety and an easy-to-reach location give families complete peace of mind every school day.","text_my":"ခေတ်မီ အဆောက်အအုံများ၊ ဂရုစိုက်သော လုံခြုံရေးစနစ်နှင့် သွားလာရလွယ်ကူသော တည်နေရာက မိသားစုတိုင်းအတွက် ကျောင်းနေရသမျှ စိတ်ချမ်းသာမှု ပေးပါသည်။"},{"icon":"🌟","title_en":"Quality Education for All","title_my":"အားလုံးအတွက် အရည်အချင်းပြည့်မီ ပညာရေး","text_en":"Every student is known, valued and inspired to reach their full potential — international-quality education made accessible to families in Myanmar.","text_my":"ကျောင်းသားတိုင်းကို သိရှိနားလည်ကာ တန်ဖိုးထားပြီး မိမိ၏ အလားအလာ အပြည့်အဝ ရောက်ရှိရန် စေ့ဆော်ပေးပါသည် — နိုင်ငံတကာအရည်အသွေးမြင့် ပညာရေးကို မြန်မာမိသားစုများ ရရှိနိုင်အောင် ပြုလုပ်ပေးပါသည်။"}]}','{"title_en":"Why Choose Hope?","title_my":"Hope ကို ဘာကြောင့် ရွေးချယ်သင့်သလဲ။","items":[{"icon":"🏫","title_en":"International Standards","title_my":"နိုင်ငံတကာ စံနှုန်းများ","text_en":"A balanced international curriculum from Early Years to Grade 12 — taught in English with Myanmar language and culture at its heart, opening doors to universities worldwide.","text_my":"နို့ဆိုင်းမှ ဂရိတ် ၁၂ အထိ မျှတသော နိုင်ငံတကာ သင်ရိုးညွှန်းတမ်း — အင်္ဂလိပ်ဘာသာဖြင့် သင်ကြားပြီး မြန်မာဘာသာနှင့် ယဉ်ကျေးမှုကို အခြေခံထားကာ ကမ္ဘာ့တက္ကသိုလ်များဆီ လမ်းဖွင့်ပေးပါသည်။"},{"icon":"👩‍🏫","title_en":"Experienced Teachers","title_my":"အတွေ့အကြုံရှိ ဆရာ ဆရာမများ","text_en":"40+ qualified teachers and a 1:15 teacher–student ratio mean small classes, individual attention and role models who care about every child.","text_my":"အရည်အချင်းပြည့်မီ ဆရာ ဆရာမ ၄၀ ကျော်နှင့် ဆရာ–ကျောင်းသား ၁:၁၅ အချိုးကြောင့် အတန်းငယ်များ၊ တစ်ယောက်ချင်း ဂရုစိုက်မှုနှင့် ကလေးတိုင်းကို ချစ်မြတ်နိုးသော ဆရာကောင်းများ ရရှိပါသည်။"},{"icon":"🧠","title_en":"Mind Education","title_my":"စိတ်ပညာရေး","text_en":"Mind education lectures by visiting experts — like Professor Dr. Gu Gyeong Hwa from Korea — and character education woven into daily learning build confidence, empathy and healthy attitudes.","text_my":"ကိုရီးယားနိုင်ငံမှ ဒေါက်တာ Gu Gyeong Hwa ကဲ့သို့ ကျွမ်းကျင်သူများ၏ စိတ်ပညာရေး ဟောပြောချက်များနှင့် နေ့စဉ်သင်ကြားမှုထဲတွင် ထည့်သွင်းထားသော စရိုက်ပညာတို့က ယုံကြည်မှု၊ သနားကြင်နာမှုနှင့် ကျန်းမာသော စိတ်သဘောထားများ ဖြစ်စေပါသည်။"},{"icon":"⚽","title_en":"Extra-Curricular Activities","title_my":"ပြင်ပလှုပ်ရှားမှုများ","text_en":"Football, basketball, swimming, robotics, music and traditional Myanmar arts — a wide range of activities helps every student discover their strengths beyond the classroom.","text_my":"ဘောလုံး၊ ဘတ်စကက်ဘော၊ ရေကူး၊ စက်ရုပ်၊ တေးဂီတနှင့် မြန်မာရိုးရာအနုပညာ — ပြင်ပလှုပ်ရှားမှုများစွာက ကျောင်းသားတိုင်း၏ စွမ်းရည်ထူးချွန်မှုကို စာသင်ခန်းပြင်ပတွင် ရှာဖွေတွေ့ရှိစေပါသည်။"},{"icon":"🛡️","title_en":"Facilities, Safety & Location","title_my":"အဆောက်အအုံ၊ လုံခြုံရေးနှင့် တည်နေရာ","text_en":"Modern facilities, a caring culture of safety and an easy-to-reach location give families complete peace of mind every school day.","text_my":"ခေတ်မီ အဆောက်အအုံများ၊ ဂရုစိုက်သော လုံခြုံရေးစနစ်နှင့် သွားလာရလွယ်ကူသော တည်နေရာက မိသားစုတိုင်းအတွက် ကျောင်းနေရသမျှ စိတ်ချမ်းသာမှု ပေးပါသည်။"},{"icon":"🌟","title_en":"Quality Education for All","title_my":"အားလုံးအတွက် အရည်အချင်းပြည့်မီ ပညာရေး","text_en":"Every student is known, valued and inspired to reach their full potential — international-quality education made accessible to families in Myanmar.","text_my":"ကျောင်းသားတိုင်းကို သိရှိနားလည်ကာ တန်ဖိုးထားပြီး မိမိ၏ အလားအလာ အပြည့်အဝ ရောက်ရှိရန် စေ့ဆော်ပေးပါသည် — နိုင်ငံတကာအရည်အသွေးမြင့် ပညာရေးကို မြန်မာမိသားစုများ ရရှိနိုင်အောင် ပြုလုပ်ပေးပါသည်။"}]}','2026-09-10T16:36:21.959402+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('contact_content','{"hero_title_en":"Contact Us","hero_title_my":"ဆက်သွယ်ရန်","hero_subtitle_en":"We would love to hear from you. Visit us, call, message or send an email — our team replies within one working day.","hero_subtitle_my":"သင့်၏ အသံကို ကြားနာချင်ပါသည်။ လာရောက်လည်ပတ်ပါ၊ ဖုန်းခေါ်ပါ၊ မက်ဆေ့ပို့ပါ သို့မဟုတ် အီးမေးလ်ပို့ပါ — ကျွန်ုပ်တို့အဖွဲ့မှ တစ်ရက်အတွင်း ပြန်ကြားပေးပါမည်။","address_title_en":"Visit Us","address_title_my":"လာရောက်လည်ပတ်ရန်","address_en":"No. 514(B), near Kyauk Gyi Taw Field, Bodo Dote Kone Village, Hlaing Tharyar Township, Yangon, Myanmar","address_my":"အမှတ် ၅၁၄ (ဘီ)၊ ကျောင်းကြီးတောကွင်းအနီး၊ ဘိုးဒေါနကုန်းကျေးရွာ၊ မှော်ဘီမြို့နယ်။","phone_title_en":"Call Us","phone_title_my":"ဖုန်းဆက်ရန်","phone_en":"+95 9 944 188 288","phone_my":"+95 9 944 188 288","email_title_en":"Email Us","email_title_my":"အီးမေးလ်ပို့ရန်","email_en":"admin@hopeinternationalschool.com","email_my":"info@hopeinternationalschool.com","hours_title_en":"Opening Hours","hours_title_my":"ဖွင့်လှစ်ချိန်","hours_en":"Mon – Fri: 8:00 AM – 4:30 PM","hours_my":"တနင်္လာ – သောကြာ: နံနက် ၈:၀၀ – ညနေ ၄:၃၀","socials":[{"kind":"facebook","href":"https://www.facebook.com/profile.php?id=61575478388604","label_en":"Follow us on Facebook","label_my":"Facebook တွင် စောင့်ကြည့်ပါ"},{"kind":"telegram","href":"https://t.me/","label_en":"Chat on Telegram","label_my":"Telegram ဖြင့် စကားပြောပါ"},{"kind":"viber","href":"viber://chat?number=%2B959944188288","label_en":"Chat on Viber","label_my":"Viber ဖြင့် စကားပြောပါ"}],"map_embed_url":"https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d3816.5621763608515!2d96.092716!3d17.133991!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zMTfCsDA4JzAyLjQiTiA5NsKwMDUnMzMuOCJF!5e0!3m2!1sen!2smm!4v1789099323608!5m2!1sen!2smm","map_title_en":"Find Us on the Map","map_title_my":"မြေပုံပေါ်တွင် ရှာဖွေပါ","map_link_url":"https://www.google.com/maps/place/17%C2%B008''02.4%22N+96%C2%B005