INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('header_content','{"logo_url":"/Logo.jpg","links":[{"href":"/","label_en":"Home","label_my":"မူလစာမျက်နှာ"},{"href":"/about","label_en":"About Us","label_my":"ကျွန်ုပ်တို့အကြောင်း"},{"href":"/academics","label_en":"Academics","label_my":"ပညာရေး"},{"href":"/news","label_en":"News & Events","label_my":"သတင်းနှင့် ပွဲများ"},{"href":"/gallery","label_en":"Gallery","label_my":"ဓာတ်ပုံပြခန်း"},{"href":"/downloads","label_en":"Downloads","label_my":"ဒေါင်းလုဒ်များ"}]}','{"logo_url":"/Logo.jpg","links":[{"href":"/","label_en":"Home","label_my":"မူလစာမျက်နှာ"},{"href":"/about","label_en":"About Us","label_my":"ကျွန်ုပ်တို့အကြောင်း"},{"href":"/academics","label_en":"Academics","label_my":"ပညာရေး"},{"href":"/news","label_en":"News & Events","label_my":"သတင်းနှင့် ပွဲများ"},{"href":"/gallery","label_en":"Gallery","label_my":"ဓာတ်ပုံပြခန်း"},{"href":"/downloads","label_en":"Downloads","label_my":"ဒေါင်းလုဒ်များ"}]}','2026-09-10T02:51:41.25406+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('home_hero_badge','Hope International School','Hope အပြည်ပြည်ဆိုင်ရာ ကျောင်း','2026-09-09T04:34:22.682142+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('home_hero_subtitle','A world-class international education in Myanmar — from Early Years to High School, where students learn in English and Burmese, grow in confidence, and become caring leaders of tomorrow.','မြန်မာနိုင်ငံရှိ ကမ္ဘာ့အဆင့်မီ နိုင်ငံတကာပညာရေး — မူကြိုမှ အထက်တန်းအထိ၊ အင်္ဂလိပ်နှင့် မြန်မာဘာသာ နှစ်မျိုးလုံးဖြင့် သင်ယူပြီး ယုံကြည်မှု တည်ဆောက်ကာ နောင်တွင် ကြင်နာတတ်သော ခေါင်းဆောင်များ ဖြစ်လာစေရန် ပြုစုပေးပါသည်။','2026-09-09T04:34:22.682142+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('home_hero_title','Nurturing Global Citizens, One Student at a Time','ကမ္ဘာ့နိုင်ငံသားကောင်းများကို ပြုစုပျိုးထောင်ခြင်း','2026-09-09T04:34:22.682142+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('home_welcome_text','At Hope International School, we believe every child is unique. Our caring teachers, modern facilities and a balanced international curriculum help each student discover their strengths, think critically and act with kindness.','Hope အပြည်ပြည်ဆိုင်ရာကျောင်းတွင် ကလေးတိုင်းသည် ထူးခြားသည်ဟု ကျွန်ုပ်တို့ ယုံကြည်ပါသည်။ ဂရုစိုက်တတ်သော ဆရာ ဆရာမများ၊ ခေတ်မီသော သင်ကြားရေးအဆောက်အအုံများနှင့် မျှတသော နိုင်ငံတကာ သင်ရိုးညွှန်းတမ်းသည် ကျောင်းသားတိုင်း မိမိ၏ အရည်အချင်းများကို ရှာဖွေတွေ့ရှိနိုင်ရန် ကူညီပေးပါသည်။','2026-09-09T04:34:22.682142+00:00');
INSERT INTO "site_content" ("key","value_en","value_my","updated_at") VALUES('home_welcome_title','Welcome to Our School','ကျောင်းမှ ကြိုဆိုပါသည်','2026-09-09T04:34:22.682142+00:00');
