INSERT INTO "gallery" ("id","image_url","caption_en","caption_my","album_en","album_my","album_desc_en","album_desc_my","created_at") VALUES('6d018ff2-0727-405d-b276-5251074fc9c8','/api/img/gallery/1788970092368-84irb0xm.jpg','🚀 A School Where Learning Comes Alive','🚀 A School Where Learning Comes Alive','🚀 A School Where Learning Comes Alive','🚀 A School Where Learning Comes Alive','May 9 ရက်နေ့တွင် HOPE International School ၌ ကျင်းပပြုလုပ်ခဲ့သော One Day English Trial Class အစီအစဉ်သည် ကလေးများ၏ ရယ်မောပျော်ရွှင်သံများ၊ မိဘများ၏ စိတ်ဝင်စားမှုများနှင့်အတူ အထူးအောင်မြင်စွာ ပြီးဆုံးခဲ့ပါသည်။ ✨ English Class, Art & Crafts Class နှင့် Mother’s Day Special Program များကို activity-based learning ပုံစံဖြင့် ပြုလုပ်ပေးခဲ့ရာ ကလေးများသည် သင်ယူခြင်းကို ပျော်ရွှင်စွာ ခံစားနိုင်ခဲ့ကြပါသည်။ 🎨📚💐 Trial Class တစ်ရက်တည်းအတွင်း ⭐ Students & Parents (100) ကျော် တက်ရောက်ခဲ့ပြီး ⭐ Enrollment Inquiry များ သိသိသာသာ တိုးလာခဲ့ကာ ⭐ HOPE International School ၏ learning environment ကို မိဘများက အထူးစိတ်ဝင်စားခဲ့ကြပါသည်။ HOPE International School တွင် ✔️ English Speaking Environment ✔️ Modern & Creative Teaching Methods ✔️ Confidence Building Activities ✔️ International Style Learning Experience ✔️ Warm & Student-Friendly Environment ✔️ Mind Education  များဖြင့် ကလေးများ၏ future skills များကို ဖွံ့ဖြိုးတိုးတက်စေရန် အဓိကထား သင်ကြားပေးလျက်ရှိပါသည်။ 🌍✨','May 9 ရက်နေ့တွင် HOPE International School ၌ ကျင်းပပြုလုပ်ခဲ့သော One Day English Trial Class အစီအစဉ်သည် ကလေးများ၏ ရယ်မောပျော်ရွှင်သံများ၊ မိဘများ၏ စိတ်ဝင်စားမှုများနှင့်အတူ အထူးအောင်မြင်စွာ ပြီးဆုံးခဲ့ပါသည်။ ✨ English Class, Art & Crafts Class နှင့် Mother’s Day Special Program များကို activity-based learning ပုံစံဖြင့် ပြုလုပ်ပေးခဲ့ရာ ကလေးများသည် သင်ယူခြင်းကို ပျော်ရွှင်စွာ ခံစားနိုင်ခဲ့ကြပါသည်။ 🎨📚💐 Trial Class တစ်ရက်တည်းအတွင်း ⭐ Students & Parents (100) ကျော် တက်ရောက်ခဲ့ပြီး ⭐ Enrollment Inquiry များ သိသိသာသာ တိုးလာခဲ့ကာ ⭐ HOPE International School ၏ learning environment ကို မိဘများက အထူးစိတ်ဝင်စားခဲ့ကြပါသည်။ HOPE International School တွင် ✔️ English Speaking Environment ✔️ Modern & Creative Teaching Methods ✔️ Confidence Building Activities ✔️ International Style Learning Experience ✔️ Warm & Student-Friendly Environment ✔️ Mind Education  များဖြင့် ကလေးများ၏ future skills များကို ဖွံ့ဖြိုးတိုးတက်စေရန် အဓိကထား သင်ကြားပေးလျက်ရှိပါသည်။ 🌍✨','2026-09-09T16:08:13.479794+00:00');
